                most_common_value, most_common_count = max(counts.items(), key=lambda x: x[1])
                # If majority has at least 3 neighbors and current value doesn't match
                if not (v == most_common_value and most_common_count >= 3):
                    if most_common_count >= 3:
                        result[r][c] = most_common_value
                    else:
                        result[r][c] = bg
