def transform_h(grid, bg):
    """Consider only horizontal neighbors"""
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg:
                continue

            left = grid[r][c-1] if c > 0 else bg
            right = grid[r][c+1] if c < w-1 else bg

            if left != bg and right != bg:
                if left == right:
                    # Both horizontal neighbors same, use that
                    result[r][c] = left
                elif right != left:
                    # Different horizontal neighbors
                    result[r][c] = bg
            elif left != bg:
                # Only left non-bg neighbor matches current, keep
                if v == left:
                    result[r][c] = v
                else:
                    result[r][c] = bg
            elif right != bg:
                # Only right non-bg neighbor matches current, keep
                if v == right:
                    result[r][c] = v
                else:
                    result[r][c] = bg

    return result

