def transform_final(grid, bg):
    """
    Rule: For each non-bg cell, check non-bg neighbors.
    - If there's a single non-bg value that appears >= 3 times among neighbors, use that value
    - Otherwise, become background
    """
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg:
                continue

            neighbor_values = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        neighbor_values.append(grid[nr][nc])

            # Count non-bg neighbors by value
            values_dict = {}
            for nv in neighbor_values:
                if nv != bg:
                    values_dict[nv] = values_dict.get(nv, 0) + 1

            if not values_dict:
                # No non-bg neighbors
                result[r][c] = bg
            else:
                # Find value with max count
                max_val, max_count = max(values_dict.items(), key=lambda x: x[1])
                if max_count >= 3:
                    result[r][c] = max_val
                else:
                    result[r][c] = bg

    return result

